Definition tfa3_1RB1RA_1LC0RA_1RB1LD_0LB0LD_vis (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 0, (StA, S0) => [SWin 1;SCycR 2;SWinR 3]
  | 0, (StA, S1) => [SWin 1]
  | 0, (StB, S0) => [SWin 1;SCycR 2;SWinR 4]
  | 0, (StB, S1) => [SWin 0]
  | 0, (StC, S1) => [SWin 1;SCycR 2;SWinR 5]
  | 0, (StD, S0) => [SWin 1;SCycR 2;SWin 2;SWinR 6;SCycL 2 0;SWin 1]
  | 0, (StD, S1) => [SWin 1;SCycR 2;SWinR 6]
  | _, _ => []
  end.

Definition tfa3_1RB1RA_1LC0RA_1RB1LD_0LB0LD_vsegs (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 0, (StA, S0) => []
  | 0, (StA, S1) => []
  | 0, (StB, S0) => []
  | 0, (StB, S1) => []
  | 0, (StC, S1) => []
  | 0, (StD, S0) => []
  | 0, (StD, S1) => []
  | _, _ => []
  end.

