(** *** The two counters at the pivot *)
Definition tL_1RB1RA_1LC0RA_1RB1LD_0LB0LD (p : nat) : list Sym := match p with | 0 => [S1] | 1 => [S1;S0;S1] | 2 => [S1;S1;S0;S1;S0;S1] | _ => [S1;S0;S0;S1;S0;S1] end.
Definition tR_1RB1RA_1LC0RA_1RB1LD_0LB0LD (p : nat) : list Sym := [S1;S1].
Definition incL_1RB1RA_1LC0RA_1RB1LD_0LB0LD (x : list bool) (p : nat) : list bool * nat :=
  if alltrue x then match p with | 0 => (repeat false (length x), 1) | 1 => (repeat false (length x), 2) | 2 => (repeat false (length x), 3) | _ => (repeat false (length x) ++ [true], 0) end else (binc x, p).
Definition incR_1RB1RA_1LC0RA_1RB1LD_0LB0LD (x : list bool) (p : nat) : list bool * nat :=
  if alltrue x then (repeat false (S (length x)), 0) else (binc x, p).

Definition aC_1RB1RA_1LC0RA_1RB1LD_0LB0LD (s : (list bool * nat) * (list bool * nat)) : cconf :=
